 808→// computeReachableFromMain returns a set of commit hashes on the main/default branch's first-parent chain.
 809→// On the default branch itself, returns an empty map (no filtering needed).
 810→// Only first-parent commits are included — commits from side branches merged into main are excluded,
 811→// since those could be feature branch commits that shouldn't be filtered out.
 812→func computeReachableFromMain(repo *git.Repository) map[plumbing.Hash]bool {
 813→	reachableFromMain := make(map[plumbing.Hash]bool)
 814→
 815→	isOnDefault, _ := strategy.IsOnDefaultBranch(repo)
 816→	if isOnDefault {
 817→		return reachableFromMain // No filtering needed on default branch
 818→	}
 819→
 820→	// Resolve main branch hash
 821→	var mainBranchHash plumbing.Hash
 822→	if defaultBranchName := strategy.GetDefaultBranchName(repo); defaultBranchName != "" {
 823→		ref, refErr := repo.Reference(plumbing.ReferenceName("refs/heads/"+defaultBranchName), true)
 824→		if refErr != nil {
 825→			ref, refErr = repo.Reference(plumbing.ReferenceName("refs/remotes/origin/"+defaultBranchName), true)
 826→		}
 827→		if refErr == nil {
 828→			mainBranchHash = ref.Hash()
 829→		}
 830→	}
 831→	if mainBranchHash == plumbing.ZeroHash {
 832→		mainBranchHash = strategy.GetMainBranchHash(repo)
 833→	}
 834→	if mainBranchHash == plumbing.ZeroHash {
 835→		return reachableFromMain
 836→	}
 837→
 838→	// Walk main's first-parent chain to build the set
 839→	_ = walkFirstParentCommits(repo, mainBranchHash, 1000, func(c *object.Commit) error { //nolint:errcheck // Best-effort
 840→		reachableFromMain[c.Hash] = true
 841→		return nil
 842→	})
 843→
 844→	return reachableFromMain
 845→}
