 847→// walkFirstParentCommits walks the first-parent chain starting from `from`,
 848→// calling fn for each commit. It stops after visiting `limit` commits (0 = no limit).
 849→// This avoids the full DAG traversal that repo.Log() does, which follows ALL parents
 850→// of merge commits and can walk into unrelated branch history (e.g., main's full
 851→// history after merging main into a feature branch).
 852→func walkFirstParentCommits(repo *git.Repository, from plumbing.Hash, limit int, fn func(*object.Commit) error) error {
 853→	current, err := repo.CommitObject(from)
 854→	if err != nil {
 855→		return fmt.Errorf("failed to get commit %s: %w", from, err)
 856→	}
 857→
 858→	for count := 0; limit <= 0 || count < limit; count++ {
 859→		if err := fn(current); err != nil {
 860→			if errors.Is(err, errStopIteration) {
 861→				return nil
 862→			}
 863→			return err
 864→		}
 865→
 866→		// Follow first parent only (skip merge parents).
 867→		// When there are no parents or parent lookup fails, we've reached the
 868→		// end of the chain — this is a normal termination, not an error.
 869→		if current.NumParents() == 0 {
 870→			return nil
 871→		}
 872→		parentHash := current.Hash
 873→		current, err = current.Parent(0)
 874→		if err != nil {
 875→			return fmt.Errorf("failed to load first parent of commit %s: %w", parentHash, err)
 876→		}
 877→	}
 878→	return nil
 879→}
